def can_dodge_ships(n, m, ships):
    # Create a set of ship positions for quick lookup
    ship_positions = set()
    for x1, x2, y in ships:
        for x in range(x1, x2 + 1):
            ship_positions.add((x, y))

    # Initialize the DP table
    dp = [[False] * (n + 1) for _ in range(2 * n + 1)]
    dp[n][0] = True

    # Fill the DP table
    for t in range(1, n + 1):
        for x in range(-n, n + 1):
            y = t
            if dp[x + n][y - 1]:
                dp[x + n][y] = True
            if dp[x + n][y]:
                dp[x + n][y] = True
            if dp[x + n][y + 1]:
